//! Writes a config as readable, deterministic TOML. The output loads back with [`crate::toml::load`]
//! to the same configuration; field order and list order are fixed, and passwords appear only as hashes.
use crate::asconfig::AsConfig;
use crate::host::HostConfig;
use config::Config;

/// First line of every generated file; the GUI edits only files that carry it structurally.
pub const HEADER: &str = "# generated by archstaller-gui";

/// Formats an AUR package list as a TOML `[[packages.aur]]` block.
pub fn aur_block(aur: &[config::AurPackage]) -> String {
    if aur.is_empty() {
        return String::new();
    }
    let mut o = String::new();
    o.push_str(
        "# Built on the installed system at its first boot, from the pinned and reviewed recipe.\n",
    );
    for a in aur {
        o.push_str("[[packages.aur]]\n");
        o.push_str(&format!("name = \"{}\"\n", a.name));
        o.push_str(&format!("pkgbase = \"{}\"\n", a.pkgbase));
        o.push_str(&format!("commit = \"{}\"\n", a.commit));
        o.push_str(&format!("sha256 = \"{}\"\n", a.sha256));
        if a.vcs {
            o.push_str("vcs = true\n");
        }
        if a.as_dep {
            o.push_str("as_dep = true\n");
        }
        if !a.deps.is_empty() {
            o.push_str(&format!("deps = {:?}\n", a.deps));
        }
        if !a.build_deps.is_empty() {
            o.push_str(&format!("build_deps = {:?}\n", a.build_deps));
        }
        if !a.services.is_empty() {
            o.push_str(&format!("services = {:?}\n", a.services));
        }
        o.push('\n');
    }
    o
}

/// Renders the configuration as standard TOML.
pub fn to_toml(cfg: &Config, host: &HostConfig) -> String {
    let a = AsConfig::from_parts(cfg, host);
    let body = toml::to_string_pretty(&a).expect("AsConfig serializes to TOML");
    format!("{HEADER}\n# Edit by hand or with archstaller-gui. Password hashes only, never plaintext.\n\n{body}")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn round_trips_through_the_loader() {
        let cfg = Config {
            hostname: "testhost".into(),
            timezone: "Europe/Prague".into(),
            locale: "en_US.UTF-8".into(),
            keymap: "cz".into(),
            disk: config::Disk {
                model: Some("Samsung".into()),
                confirm_serial: "S12345".into(),
                auto_largest: false,
                esp_mib: 512,
            },
            mirrors: vec!["https://geo.mirror.pkgbuild.com/$repo/os/$arch".into()],
            packages: vec!["base".into(), "linux".into(), "grub".into()],
            providers: vec![("initramfs".into(), "mkinitcpio".into())],
            root_password_hash: Some("$6$xyz".into()),
            users: vec![config::User {
                name: "alice".into(),
                password_hash: "$6$abc".into(),
                groups: vec!["wheel".into()],
                shell: "/bin/bash".into(),
            }],
            services: vec!["sshd.service".into()],
            kernel_params: vec!["quiet".into()],
            user_files: vec![],
            user_archives: vec![],
            dry_run: false,
            scripts: vec![],
            custom_services: vec![],
            aur: vec![],
        };
        let host = HostConfig {
            build: crate::host::Build {
                profile: Some("large".into()),
                tethering: true,
            },
            installer_drivers: Some(vec!["e1000".into()]),
        };

        let toml_text = to_toml(&cfg, &host);
        assert!(toml_text.starts_with(HEADER));

        let loaded =
            crate::toml::load_str_unvalidated(&toml_text, std::path::Path::new(".")).unwrap();
        assert_eq!(loaded.config.hostname, cfg.hostname);
        assert_eq!(loaded.config.keymap, cfg.keymap);
        assert_eq!(loaded.config.disk.confirm_serial, cfg.disk.confirm_serial);
        assert_eq!(loaded.config.packages, cfg.packages);
        assert_eq!(loaded.host.build.tethering, host.build.tethering);
        assert_eq!(loaded.host.build.profile, host.build.profile);
    }
}
